# Weekly report

tracker.json is the export of the team's issue tracker. report.py turns it into the weekly report.
import json


def open_count(issues):
    return sum(1 for i in issues if i["state"] == "open")


def weekly_report(path="tracker.json"):
    with open(path, encoding="utf-8") as f:
        issues = json.load(f)
    return f"Open issues: {open_count(issues)}"
import unittest

from report import open_count


class ReportTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(open_count([]), 0)


if __name__ == "__main__":
    unittest.main()
